PRAGMA foreign_keys=ON;
CREATE TABLE ExecutionEditTestSentinel(Name TEXT PRIMARY KEY);
INSERT INTO ExecutionEditTestSentinel VALUES('EXECUTION_EDIT_TEST');
CREATE TABLE users(user_id INTEGER PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL DEFAULT 'test',is_active INTEGER NOT NULL DEFAULT 1,name TEXT);
CREATE TABLE roles(role_id INTEGER PRIMARY KEY,role_name TEXT UNIQUE NOT NULL,description TEXT);
CREATE TABLE user_roles(user_id INTEGER REFERENCES users(user_id),role_id INTEGER REFERENCES roles(role_id),PRIMARY KEY(user_id,role_id));
CREATE TABLE DanhSachMaSP(id INTEGER PRIMARY KEY,Ten TEXT,Ma TEXT UNIQUE,DonVi TEXT DEFAULT 'm',KieuSP TEXT DEFAULT 'TP');
CREATE TABLE TTThanhPham(id INTEGER PRIMARY KEY,DanhSachSP_ID INTEGER REFERENCES DanhSachMaSP(id),MaBin TEXT UNIQUE,NhapKho INTEGER DEFAULT 1,Temp INTEGER DEFAULT 0,Active INTEGER DEFAULT 1);
CREATE TABLE TTNhapKhoTP(id INTEGER PRIMARY KEY,TTThanhPham_ID INTEGER REFERENCES TTThanhPham(id),NgayNhapKho TEXT,DateInsert TEXT,TenSP TEXT DEFAULT '',TongChieuDai REAL DEFAULT 0,GhiChu TEXT DEFAULT '',NguoiLam TEXT DEFAULT '');
CREATE TABLE TTCuonDay(id INTEGER PRIMARY KEY AUTOINCREMENT,ThongTinNhapKho_ID INTEGER NOT NULL REFERENCES TTNhapKhoTP(id),SoCuon INTEGER,ChieuDai_1cuon INTEGER,SoDau INTEGER,SoCuoi INTEGER,Ngay TEXT,DateInsert TEXT);
CREATE TABLE KeHoach(id INTEGER PRIMARY KEY AUTOINCREMENT,MaKeHoach TEXT UNIQUE,NgayKeHoach TEXT,Users_id INTEGER REFERENCES users(user_id),TrangThai TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(TrangThai IN('ACTIVE','HUY')),NguoiNhan TEXT,GhiChu TEXT,NguoiTao TEXT,DateInsert TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE KeHoachHang(id INTEGER PRIMARY KEY AUTOINCREMENT,KeHoach_ID INTEGER NOT NULL REFERENCES KeHoach(id),DanhSachMaSP_ID INTEGER NOT NULL REFERENCES DanhSachMaSP(id),SoLuongCuonCanLay INTEGER DEFAULT 0,ChieuDai1Cuon_KeHoach INTEGER,UNIQUE(KeHoach_ID,DanhSachMaSP_ID));
CREATE TABLE KeHoachHangQuyCachCuonChan(id INTEGER PRIMARY KEY AUTOINCREMENT,KeHoachHang_ID INTEGER NOT NULL REFERENCES KeHoachHang(id),ChieuDai1Cuon INTEGER NOT NULL,SoLuongCuonCanLay INTEGER NOT NULL DEFAULT 0,UNIQUE(KeHoachHang_ID,ChieuDai1Cuon));
CREATE TABLE TonCuonLe(id INTEGER PRIMARY KEY AUTOINCREMENT,MaCuon TEXT NOT NULL UNIQUE,TTThanhPham_ID INTEGER NOT NULL REFERENCES TTThanhPham(id),TTCuonDay_ID INTEGER NOT NULL REFERENCES TTCuonDay(id),SoDau INTEGER NOT NULL,SoCuoi INTEGER NOT NULL,TrangThai TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(TrangThai IN('ACTIVE','HET')),GhiChu TEXT,DateInsert TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE KeHoachCatNhom(id INTEGER PRIMARY KEY AUTOINCREMENT,KeHoachHang_ID INTEGER NOT NULL REFERENCES KeHoachHang(id),TonCuonLe_ID INTEGER REFERENCES TonCuonLe(id),QuyCachCuonChan_ID INTEGER REFERENCES KeHoachHangQuyCachCuonChan(id),GhiChu TEXT,DateInsert TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE KeHoachCatChiTiet(id INTEGER PRIMARY KEY AUTOINCREMENT,KeHoachCatNhom_ID INTEGER NOT NULL REFERENCES KeHoachCatNhom(id),ChieuDaiCanCat INTEGER NOT NULL CHECK(ChieuDaiCanCat>0),GhiChu TEXT,DateInsert TEXT DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE LichSuLayCuon(id INTEGER PRIMARY KEY AUTOINCREMENT,KeHoachHang_ID INTEGER NOT NULL REFERENCES KeHoachHang(id),TTCuonDay_ID INTEGER NOT NULL REFERENCES TTCuonDay(id),QuyCachCuonChan_ID INTEGER REFERENCES KeHoachHangQuyCachCuonChan(id),SoLuong INTEGER NOT NULL CHECK(SoLuong>0),NguoiThucHien TEXT NOT NULL,ThoiGianThucHien TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,GhiChu TEXT);
CREATE TABLE LichSuCat(id INTEGER PRIMARY KEY AUTOINCREMENT,KeHoachCatChiTiet_ID INTEGER NOT NULL UNIQUE REFERENCES KeHoachCatChiTiet(id),TonCuonLe_ID INTEGER NOT NULL REFERENCES TonCuonLe(id),LoaiNguon TEXT NOT NULL CHECK(LoaiNguon IN('CUON_CHAN','CUON_LE')),ChieuDaiCat INTEGER NOT NULL CHECK(ChieuDaiCat>0),SoDauTruoc INTEGER NOT NULL,SoCuoiTruoc INTEGER NOT NULL,SoDauCat INTEGER NOT NULL,SoCuoiCat INTEGER NOT NULL,SoDauSau INTEGER NOT NULL,SoCuoiSau INTEGER NOT NULL,HeSoChieu INTEGER NOT NULL CHECK(HeSoChieu IN(-1,1)),MaQuetThucTe TEXT NOT NULL,NguoiThucHien TEXT NOT NULL,ThoiGianThucHien TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,GhiChu TEXT,DieuChinhThongSo TEXT);
CREATE TABLE B3QrSuDung(RawQr TEXT COLLATE BINARY PRIMARY KEY NOT NULL,TrangThai TEXT NOT NULL CHECK(TrangThai IN('DA_LAY_NGUYEN','DA_CHUYEN_LE')),LichSuLayCuon_ID INTEGER REFERENCES LichSuLayCuon(id),TonCuonLe_ID INTEGER REFERENCES TonCuonLe(id),NguoiThucHien TEXT NOT NULL,ThoiGian TEXT DEFAULT CURRENT_TIMESTAMP,CHECK((TrangThai='DA_LAY_NGUYEN' AND LichSuLayCuon_ID IS NOT NULL AND TonCuonLe_ID IS NULL) OR (TrangThai='DA_CHUYEN_LE' AND LichSuLayCuon_ID IS NULL AND TonCuonLe_ID IS NOT NULL)));
